/// <summary>
/// Finds the indirect component group of an hour line in the indirect cost matrix
/// (<c>HOGpmaIndirectCostMatrix</c>), from the employment category and the cost center
/// of the worker's employment in the current legal entity on the transaction date.
/// </summary>
/// <remarks>
/// Search order: employment category Table, Group, All; within each, cost center Table, Group, All.
/// The All / All line is the fallback. Results are cached per worker, date and legal entity
/// for the duration of the transaction.
/// </remarks>
public final class HOGpmaIndirectCostMatrixLookup
{
}

Method.Source:
/// <summary>
/// Finds the indirect component group for a resource on a date.
/// </summary>
/// <param name = "_resource">The resource of the hour line.</param>
/// <param name = "_transDate">The project transaction date of the hour line.</param>
/// <returns>The indirect component group, or an empty string if the resource is not a worker or no matrix line matches.</returns>
public static PSAIndirectComponentGroupId findGroupForResource(ResourceRecId _resource, TransDate _transDate)
{
    PSAIndirectComponentGroupId groupId;
    HcmWorkerRecId              worker = ResourceFacade::getWorker(_resource);

    if (worker)
    {
        CompanyInfoRecId    legalEntity = CompanyInfo::current();
        str                 scope       = HOGpmaIndirectCostMatrixLookup::cacheScope();
        container           cacheKey    = [worker, _transDate, legalEntity];

        if (SysTransactionScopeCache::isSet(scope, cacheKey))
        {
            groupId = SysTransactionScopeCache::get(scope, cacheKey);
        }
        else
        {
            groupId = HOGpmaIndirectCostMatrixLookup::findGroupForWorker(worker, legalEntity, _transDate);
            SysTransactionScopeCache::set(scope, cacheKey, groupId);
        }
    }

    return groupId;
}

/// <summary>
/// Finds the indirect component group for a worker in a legal entity on a date, without caching.
/// </summary>
/// <param name = "_worker">The worker.</param>
/// <param name = "_legalEntity">The legal entity of the employment.</param>
/// <param name = "_transDate">The project transaction date.</param>
/// <returns>The indirect component group, or an empty string if no matrix line matches.</returns>
/// <remarks>
/// The date is converted like the standard indirect cost posting does it for the same table
/// (<c>PSAProjPostEmplIndirectJournal</c>: <c>DateTimeUtil::newDateTime(transDate, 0)</c>).
/// A worker without employment, employment category or cost center falls through to the lines
/// where that field is empty.
/// </remarks>
public static PSAIndirectComponentGroupId findGroupForWorker(
    HcmWorkerRecId      _worker,
    CompanyInfoRecId    _legalEntity,
    TransDate           _transDate)
{
    utcdatetime                 asOf        = DateTimeUtil::newDateTime(_transDate, 0);
    HcmEmployment               employment  = HcmEmployment::findByWorkerLegalEntity(_worker, _legalEntity, asOf);
    HcmEmploymentDetail         detail      = HcmEmploymentDetail::findByWorkerLegalEntity(_worker, _legalEntity, asOf);
    BenefitEmploymentCategory   category;

    if (detail.BenefitEmploymentCategoryRecId)
    {
        select firstonly EmploymentCategory from category
            where category.RecId == detail.BenefitEmploymentCategoryRecId;
    }

    return HOGpmaIndirectCostMatrixLookup::findGroup(
        category.EmploymentCategory,
        HOGpmaIndirectCostMatrixLookup::costCenter(employment.DefaultDimension),
        _transDate);
}

/// <summary>
/// Finds the best matching line of the indirect cost matrix.
/// </summary>
/// <param name = "_employmentCategory">The employment category ID; empty if the worker has none.</param>
/// <param name = "_costCenter">The cost center value; empty if none.</param>
/// <param name = "_transDate">The project transaction date.</param>
/// <returns>The indirect component group of the best matching line, or an empty string.</returns>
/// <remarks>
/// An empty field on a matrix line means all. Sorting descending puts a filled value before an empty
/// one, so the search order is: category + cost center, category only, cost center only, neither.
/// Employment category ranks above cost center; within a match, the latest valid-from date wins.
/// </remarks>
public static PSAIndirectComponentGroupId findGroup(
    BenefitEmploymentCategoryId _employmentCategory,
    DimensionValue              _costCenter,
    TransDate                   _transDate)
{
    HOGpmaIndirectCostMatrix matrix;

    select firstonly IndirectComponentGroup from matrix
        order by EmploymentCategory desc, CostCenter desc, ValidFrom desc
        where (matrix.EmploymentCategory == _employmentCategory || matrix.EmploymentCategory == '')
           && (matrix.CostCenter         == _costCenter         || matrix.CostCenter         == '')
           && matrix.ValidFrom <= _transDate;

    return matrix.IndirectComponentGroup;
}

/// <summary>
/// Reads the cost center from a default dimension, using the dimension set up in the project parameters.
/// </summary>
/// <param name = "_defaultDimension">The default dimension of the employment.</param>
/// <returns>The cost center value, or an empty string.</returns>
private static DimensionValue costCenter(DimensionDefault _defaultDimension)
{
    DimensionValue          costCenter;
    DimensionAttributeRecId costCenterAttribute = ProjParameters::find().HOGpmaCostCenterDimensionAttribute;

    if (_defaultDimension && costCenterAttribute)
    {
        costCenter = DimensionAttributeValueSetStorage::find(_defaultDimension)
            .getDisplayValueByDimensionAttribute(costCenterAttribute);
    }

    return costCenter;
}

/// <summary>
/// Gets the financial dimension that holds the cost center, as set up in the project parameters.
/// </summary>
/// <returns>The dimension attribute; an empty record if the parameter is not set.</returns>
public static DimensionAttribute costCenterDimension()
{
    return DimensionAttribute::find(ProjParameters::find().HOGpmaCostCenterDimensionAttribute);
}

/// <summary>
/// Checks that a cost center exists as a value of the cost center dimension.
/// </summary>
/// <param name = "_costCenter">The cost center value.</param>
/// <returns>true if the value exists; otherwise, false, with a message in the infolog.</returns>
public static boolean checkCostCenter(DimensionValue _costCenter)
{
    DimensionAttribute costCenterDimension = HOGpmaIndirectCostMatrixLookup::costCenterDimension();

    if (!costCenterDimension.RecId)
    {
        return checkFailed("@HOGpma:ErrCostCenterDimensionMissing");
    }

    if (!DimensionAttributeValue::findByDimensionAttributeAndValueNoError(costCenterDimension, _costCenter).RecId)
    {
        return checkFailed(strFmt("@HOGpma:ErrValueNotFound", costCenterDimension.localizedName(), _costCenter));
    }

    return true;
}

/// <summary>
/// The scope of the transaction cache.
/// </summary>
/// <returns>The cache scope.</returns>
private static str cacheScope()
{
    return classStr(HOGpmaIndirectCostMatrixLookup);
}
